            <Area type="monotone" dataKey="dry" stackId="1" fill="url(#gradientDry)" stroke="#f59e0b" />
          </AreaChart>
        </ResponsiveContainer>
      );
    }

    if (historyChart) {
      setExpandedGraph(prev => ({
        ...prev,
        title: `${prev.title} (Snapshot: ${session.date} ${session.startTime})`,
        chart: historyChart
      }));
