            <stop offset="5%" stopColor="#f59e0b" stopOpacity={0.9} />
            <stop offset="95%" stopColor="#d97706" stopOpacity={0.6} />
          </linearGradient>
        </defs>
      </svg>
      {/* Expanded Graph Modal */}
      <AnimatePresence>
        {expandedGraph && (
          <motion.div
