                >
                  <X size={24} className="text-slate-400" />
                </button>
              </div>

              {/* Modal Content Grid */}
              <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-6 min-h-0">

                {/* Sidebar: Session History */}
