import React, { useEffect, useState, useRef, useMemo } from 'react';
import { io } from 'socket.io-client';
import { Power, Activity, AlertTriangle, Webcam, Settings, Trash2, Zap, Sun, Moon, TrendingUp, BarChart2, PieChart, Recycle, Clock, ArrowUpRight, Download, BellRing, BellOff, Database, Sliders, Volume2, VolumeX, Pause, Play, Leaf, Droplets } from 'lucide-react';
import { LineChart, Line, BarChart, Bar, AreaChart, Area, PieChart as RechartsPie, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine, Legend, Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ScatterChart, Scatter, ZAxis } from 'recharts';
import clsx from 'clsx';
import { motion, AnimatePresence } from 'framer-motion';
import { AnimatedCounter, ProgressRing, Sparkline, LiveIndicator, TiltCard, MouseGlow, RippleButton } from './UIComponents';
import { LiveActivityFeed, useSwipeGesture, PullRefreshIndicator } from './AdvancedComponents';
import {
  EnhancedAreaChart, TimeRangeSelector, ChartModal,
  CompareToggle, ChartCard, CompareChart, GlassTooltip, TimelineScrubber, AnimatedBackground, PremiumRadarChart, PremiumPieChart, ConfidenceHistogram, HourlyStackedBarChart,
  PredictiveLineChart, UsageHeatmap, SustainabilityGauge
} from './ChartEnhancements';
import { SimpleDashboard } from './SimpleDashboard';
import AnalyticsDetailModal from './components/AnalyticsDetailModal';
import HistorySlider from './components/HistorySlider';
import { AnalyticsDeckWidget } from './widgets/AnalyticsDeckWidget';

const socket = io('http://localhost:3001');

// --- Graph Enhancement Components ---
// Premium 2-Color Theme: Slate + Teal
const binColors = {
  0: { main: '#14b8a6', gradient: ['#14b8a6', '#0d9488'] }, // Teal (Recyclable)
  1: { main: '#2dd4bf', gradient: ['#2dd4bf', '#14b8a6'] }, // Teal Light (Wet)
  2: { main: '#f43f5e', gradient: ['#f43f5e', '#e11d48'] }, // Rose (Hazardous)
  3: { main: '#64748b', gradient: ['#64748b', '#475569'] }  // Slate (Dry)
};

// ===== CINEMATIC LOADING SCREEN WITH WATER RIPPLES =====
const CinematicLoader = ({ progress, status }) => (
  <div className="fixed inset-0 z-[9999] bg-[#030303] flex flex-col items-center justify-center overflow-hidden">
    {/* Subtle ambient glow */}
    <div className="absolute inset-0">
      <div
        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-teal-500/5 blur-3xl"
        style={{ width: '800px', height: '800px', borderRadius: '50%' }}
      />
    </div>

    {/* Central Orb with Water Ripples */}
    <div className="relative flex items-center justify-center mb-16" style={{ width: '400px', height: '400px' }}>

      {/* Water Ripple Rings - CIRCULAR with inline borderRadius */}
      {[1, 2, 3, 4, 5, 6].map((ring) => (
        <motion.div
          key={ring}
          className="absolute"
          style={{
            width: '100px',
            height: '100px',
            borderRadius: '50%',
            border: '2px solid rgba(45, 212, 191, 0.6)',
            boxShadow: '0 0 20px rgba(45, 212, 191, 0.4), inset 0 0 15px rgba(45, 212, 191, 0.2)',
          }}
          animate={{
            width: ['100px', '380px'],
            height: ['100px', '380px'],
            opacity: [0.9, 0],
            borderWidth: ['3px', '1px'],
          }}
          transition={{
            duration: 2.5,
            repeat: Infinity,
            delay: ring * 0.4,
            ease: 'easeOut',
          }}
        />
      ))}

      {/* Static glow behind logo */}
      <div
        className="absolute bg-teal-500/30 blur-2xl"
        style={{ width: '120px', height: '120px', borderRadius: '50%' }}
      />

      {/* Circular Logo Container - PERFECT CIRCLE */}
      <motion.div
        initial={{ scale: 0, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 0.5, type: 'spring', stiffness: 200 }}
        className="relative z-10 flex items-center justify-center"
        style={{
          width: '100px',
          height: '100px',
          borderRadius: '50%',
          background: 'linear-gradient(135deg, #14b8a6 0%, #06b6d4 50%, #0d9488 100%)',
          boxShadow: '0 0 50px rgba(20, 184, 166, 0.6), 0 0 100px rgba(20, 184, 166, 0.3)',
        }}
      >
        {/* Inner dark circle */}
        <div
          className="flex items-center justify-center bg-[#0a0a0a]"
          style={{ width: '84px', height: '84px', borderRadius: '50%' }}
        >
          <motion.div
            animate={{ rotate: 360 }}
            transition={{ duration: 6, repeat: Infinity, ease: 'linear' }}
          >
            <Recycle className="w-10 h-10 text-teal-400" />
          </motion.div>
        </div>
      </motion.div>
    </div>

    {/* Title */}
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, delay: 0.3 }}
      className="relative z-10 text-center mb-8"
    >
      <h1 className="text-3xl font-bold text-white mb-1">
        <span className="text-teal-400">Smart</span> Waste Management
      </h1>
      <p className="text-slate-500 text-sm">Intelligent Classification System</p>
    </motion.div>

    {/* Progress Bar */}
    <motion.div
      initial={{ opacity: 0, scaleX: 0 }}
      animate={{ opacity: 1, scaleX: 1 }}
      transition={{ duration: 0.5, delay: 0.5 }}
      className="relative z-10 w-64"
    >
      <div className="h-1 bg-slate-800/80 overflow-hidden" style={{ borderRadius: '9999px' }}>
        <motion.div
          initial={{ width: 0 }}
          animate={{ width: `${progress}%` }}
          transition={{ duration: 0.4 }}
          className="h-full bg-gradient-to-r from-teal-500 to-cyan-400"
          style={{ borderRadius: '9999px', boxShadow: '0 0 15px rgba(20, 184, 166, 0.6)' }}
        />
      </div>
      <div className="flex justify-between mt-3 text-xs">
        <span className="text-slate-400">{status}</span>
        <span className="text-teal-400 font-mono">{progress}%</span>
      </div>
    </motion.div>
  </div>
);

const CustomTooltip = ({ active, payload, label, theme, binId }) => {
  if (active && payload && payload.length) {
    const color = binColors[binId]?.main || '#8884d8';
    return (
      <div className={clsx(
        "p-4 rounded-xl border backdrop-blur-md shadow-2xl",
        theme === 'dark' ? "bg-neutral-900/90 border-white/10 text-white" : "bg-white/80 border-white/50 text-slate-800"
      )}>
        <p className="font-mono text-xs opacity-70 mb-2">{label}</p>
        {payload.map((entry, index) => (
          <div key={index} className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }} />
            <span className="font-bold text-sm">{entry.name}:</span>
            <span className="font-mono text-sm">{entry.value}</span>
            {entry.name === 'Volume' && <span className="text-xs opacity-70">%</span>}
          </div>
        ))}
      </div>
    );
  }
  return null;
};

function App() {
  const [data, setData] = useState({
    isOn: false,
    conveyorSpeed: 'medium',
    conveyorDirection: 'forward',
    maintenanceMode: false,
    revenue: 0,
    manualServo: { 0: 0, 1: 0, 2: 0, 3: 0 },
    bins: [
      { id: 0, name: "Recyclable", type: "recyclable", weight: 0, volume: 0 },
      { id: 1, name: "Wet Waste", type: "wet", weight: 0, volume: 0 },
      { id: 2, name: "Hazardous", type: "hazard", weight: 0, volume: 0 },
      { id: 3, name: "Dry Waste", type: "dry", weight: 0, volume: 0 }
    ]
  });

  const [alert, setAlert] = useState(null);
  const [isConnected, setIsConnected] = useState(socket.connected);

  // Loading Screen State
  const [isLoading, setIsLoading] = useState(true);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [loadingStatus, setLoadingStatus] = useState('Initializing...');
  const [loadingExpanding, setLoadingExpanding] = useState(false);

  // Load Camera URL from Settings or Default
  const [camUrl, setCamUrl] = useState(() => {
    const saved = localStorage.getItem('waste_settings');
    return saved ? JSON.parse(saved).camUrl : '192.168.128.206:8080';
  });

  // Migration: Auto-update old IP to new one
  useEffect(() => {
    const saved = localStorage.getItem('waste_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.camUrl.includes('10.205.209.232') || parsed.camUrl.includes('192.168.1.3') || parsed.camUrl.includes('10.63.6.215') || parsed.camUrl.includes('192.168.128.114') || parsed.camUrl.includes('10.50.211.74')) {
        console.log("Migrating old IP to new default...");
        const newSettings = { ...parsed, camUrl: '192.168.128.206:8080' };
        localStorage.setItem('waste_settings', JSON.stringify(newSettings));
        setCamUrl('192.168.128.206:8080');
      }
    }
  }, []);

  const [hourlyData, setHourlyData] = useState([]); // Hourly stacked bar data
  const [showComparisonMode, setShowComparisonMode] = useState(false); // Toggle for comparison view
  const [drillDownCategory, setDrillDownCategory] = useState(null); // For pie drill-down

  // Voice Feedback State
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [sensitivity, setSensitivity] = useState('High'); // Low, Medium, High
  const [selectedHistorySession, setSelectedHistorySession] = useState(null); // For Detailed View Modal
  const [rotation, setRotation] = useState(0); // State for video rotation
  const [isTorchOn, setIsTorchOn] = useState(false); // State for Torch
  const [aiData, setAiData] = useState({ class: 'Scanning...', confidence: 0, label_id: -1 });
  const [boxPos, setBoxPos] = useState(null);
  // Automation Refs
  const ignoreMotionRef = useRef(0);
  const resumeTimerRef = useRef(null);
  const itemProcessedRef = useRef(false); // Track if current item is counted
  const hideTimerRef = useRef(null); // Timer for box persistence
  const lastCountTimeRef = useRef(0); // Cooldown to prevent rapid counting
  const lastInferenceTime = useRef(0); // Throttle for AI inference
  const DETECTION_COOLDOWN_MS = 2000; // Minimum 2 seconds between counts

  const [history, setHistory] = useState([]);
  const [theme, setTheme] = useState(() => {
    // Default to 'dark' for premium black look
    return localStorage.getItem('theme') || 'dark';
  });
  const [isAutoTheme, setIsAutoTheme] = useState(() => {
    return localStorage.getItem('isAutoTheme') === 'true';
  });
  const [graphType, setGraphType] = useState('line');
  const [selectedBin, setSelectedBin] = useState(null);

  // Auto Day/Night Theme Effect
  useEffect(() => {
    if (!isAutoTheme) return;

    const checkTimeAndSetTheme = () => {
      const hour = new Date().getHours();
      // Day: 6 AM - 6 PM = light, Night: 6 PM - 6 AM = dark
      const shouldBeDark = hour < 6 || hour >= 18;
      setTheme(shouldBeDark ? 'dark' : 'light');
    };

    checkTimeAndSetTheme();
    // Check every minute
    const interval = setInterval(checkTimeAndSetTheme, 60000);
    return () => clearInterval(interval);
  }, [isAutoTheme]);

  // Save auto theme preference
  useEffect(() => {
    localStorage.setItem('isAutoTheme', isAutoTheme.toString());
  }, [isAutoTheme]);

  // Load Session Data from LocalStorage
  const [eventLog, setEventLog] = useState(() => {
    const saved = localStorage.getItem('waste_session_current');
    return saved ? JSON.parse(saved).eventLog : [];
  });

  const [processingCounts, setProcessingCounts] = useState(() => {
    const saved = localStorage.getItem('waste_session_current');
    return saved ? JSON.parse(saved).processingCounts : {
      total: 0, recyclable: 0, wet: 0, hazardous: 0, dry: 0
    };
  });

  // Time-series data for charts
  const [timeSeriesData, setTimeSeriesData] = useState([]);
  const [confidenceHistory, setConfidenceHistory] = useState([]);

  // History of PAST sessions
  const [sessionHistory, setSessionHistory] = useState(() => {
    const saved = localStorage.getItem('waste_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [showHistoryModal, setShowHistoryModal] = useState(false);

  // Session History Enhancements
  const [compareMode, setCompareMode] = useState(false);
  const [selectedForCompare, setSelectedForCompare] = useState([]);
  const [historyFilter, setHistoryFilter] = useState('all'); // all, today, week, month

  // Camera Controls
  const [cameraZoom, setCameraZoom] = useState(1);
  const [cameraBrightness, setCameraBrightness] = useState(100);
  const [pipMode, setPipMode] = useState(false);

  // AI Confidence Enhancement
  const [confidenceThreshold, setConfidenceThreshold] = useState(80);
  const [lowConfidenceCount, setLowConfidenceCount] = useState(0);

  // Alerts System
  const [alertHistory, setAlertHistory] = useState([]);

  // Connection Tracking
  const [reconnectCount, setReconnectCount] = useState(0);
  const [lastConnected, setLastConnected] = useState(null);

  // Bin Fill Rate Tracking (for time prediction)
  const [binFillRates, setBinFillRates] = useState({ 0: 0, 1: 0, 2: 0, 3: 0 });
  const prevBinVolumes = useRef({ 0: 0, 1: 0, 2: 0, 3: 0 });

  // NEW: Session Timer (only when ON), Fullscreen, Notifications
  const [activeSeconds, setActiveSeconds] = useState(0);
  const [sessionDuration, setSessionDuration] = useState('00:00:00');
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [notificationEnabled, setNotificationEnabled] = useState(false);
  const [expandedGraph, setExpandedGraph] = useState(null); // For graph pop-out modal

  // Category flash animation (shows +1 Bio, +1 Haz, etc.)
  const [categoryFlash, setCategoryFlash] = useState(null); // { category: 'Recyclable', time: timestamp }

  // False positive filter (require multiple frames)
  const detectionFrameCount = useRef(0);
  const lastDetectedClass = useRef(null);
  const REQUIRED_FRAMES = 3; // Need 3+ consistent frames to confirm

  // Sound effects
  const [soundEnabled, setSoundEnabled] = useState(true);

  // Detection hour tracking for heatmap
  const [detectionHours, setDetectionHours] = useState(() => {
    const saved = localStorage.getItem('waste_detection_hours');
    return saved ? JSON.parse(saved) : Array(24).fill(0);
  });

  // Toast notifications
  const [toasts, setToasts] = useState([]);

  // Keyboard shortcuts help modal
  const [showKeyboardHelp, setShowKeyboardHelp] = useState(false);

  // Settings modal
  const [showSettings, setShowSettings] = useState(false);

  // Pause mode - camera on, counting paused
  const [isPaused, setIsPaused] = useState(false);

  // Display modes: 'full' | 'kiosk' | 'split' | 'compact' | 'widget' | 'custom'
  const [displayMode, setDisplayMode] = useState('full');
  const [isEditMode, setIsEditMode] = useState(false);

  // Event log search
  const [logSearchQuery, setLogSearchQuery] = useState('');

  // Auto night mode (torch)
  const [autoTorch, setAutoTorch] = useState(false);

  // Live activity feed state
  const [showLiveFeed, setShowLiveFeed] = useState(true);
  const [recentDetections, setRecentDetections] = useState([]);




  // Chart enhancement state (Phase 1 & 3)
  const [chartTimeRange, setChartTimeRange] = useState('all');
  const [expandedChart, setExpandedChart] = useState(null); // 'trends' | 'confidence' | null
  const [compositionChartView, setCompositionChartView] = useState('pie'); // 'pie' | 'radar'

  // History slider state (0 = live, negative = past cycles)
  const [chartHistoryIndex, setChartHistoryIndex] = useState(0);
  const [chartDataHistory, setChartDataHistory] = useState([]);
  const MAX_HISTORY_CYCLES = 30;

  // Modal State
  const [activeModal, setActiveModal] = useState(null); // 'composition', 'throughput', 'session', 'hourly', 'confidence', 'radar'
  const [historyValue, setHistoryValue] = useState(0); // 0 = live, -1 = past run 1, etc.

  // Mock History Data Generator for Sliders
  const generateMockHistory = (baseData) => {
    // Create 10 past versions with FAKE data variation (especially for Bio as requested)
    return Array.from({ length: 11 }).map((_, i) => ({
      id: i,
      timestamp: i === 0 ? "NOW" : new Date(Date.now() - i * 3600000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      data: i === 0 ? null : { // 0 is live, others are mocks
        // Fake data generation
        recyclable: Math.floor(Math.random() * 50) + 10,
        hazardous: Math.floor(Math.random() * 30) + 5,
        wet: Math.floor(Math.random() * 60) + 20,
        dry: Math.floor(Math.random() * 80) + 30,
        total: Math.floor(Math.random() * 200) + 100
      }
    })).reverse();
  };

  // Graph Info Descriptions for hover tooltips
  const MODAL_DESCRIPTIONS = {
    composition: "Shows the distribution of waste across categories (Recyclable, Wet, Hazardous, Dry). Helps identify which waste types are most common in your facility.",
    radar: "Displays waste category distribution in a radar/spider chart format. Useful for comparing relative quantities across all categories at a glance.",
    throughput: "Tracks waste detection velocity over time. Shows how processing rates change throughout the day and helps identify peak hours.",
    session: "Compares current session performance against historical averages. Helps track whether you're processing more or less waste than usual.",
    hourly: "Stacked bar chart showing hourly breakdown of waste by category. Identifies busy periods and category distribution patterns.",
    confidence: "Histogram showing AI detection confidence distribution. Higher values mean more accurate classifications.",
    predictive: "Forecasts expected waste volume based on historical patterns. Helps anticipate bin fill levels and plan collection schedules.",
    heatmap: "Visual heatmap showing activity intensity by hour. Darker colors indicate busier periods.",
    sustainability: "Environmental impact score measuring CO2 offset, trees equivalent, and energy savings from proper waste segregation."
  };

  const handleExpandChart = (chartType) => {
    setActiveModal(chartType);
    setHistoryValue(0); // Reset to live
  };

  const runs = useMemo(() => generateMockHistory(), []); // Generate usage history only once
  const getModalContent = () => {
    switch (activeModal) {
      case 'composition':
        // Pie Chart for Composition
        const pieCounts = historyValue !== 0 && runs[10 - Math.abs(historyValue)]?.data
          ? runs[10 - Math.abs(historyValue)].data
          : processingCounts;

        return <PremiumPieChart data={[
          { name: 'Recyclable', value: pieCounts.recyclable || 0 },
          { name: 'Wet', value: pieCounts.wet || 0 },
          { name: 'Hazardous', value: pieCounts.hazardous || 0 },
          { name: 'Dry', value: pieCounts.dry || 0 }
        ]} height={400} />;

      case 'radar':
        // Radar Chart
        const radarCounts = historyValue !== 0 && runs[10 - Math.abs(historyValue)]?.data
          ? runs[10 - Math.abs(historyValue)].data
          : processingCounts;

        return <PremiumRadarChart data={[
          { subject: 'Recyclable', A: radarCounts.recyclable || 0, fullMark: 100 },
          { subject: 'Wet', A: radarCounts.wet || 0, fullMark: 100 },
          { subject: 'Hazardous', A: radarCounts.hazardous || 0, fullMark: 100 },
          { subject: 'Dry', A: radarCounts.dry || 0, fullMark: 100 },
        ]} height={400} />;
      case 'throughput':
        // Enhanced Category Trends Modal with Controls
        const trendData = timeSeriesData.length > 0 ? timeSeriesData : [];
        const currentTotal = trendData[trendData.length - 1]?.total || 0;
        const previousTotal = trendData[0]?.total || 1;
        const trendDelta = Math.round(((currentTotal / Math.max(1, previousTotal)) - 1) * 100);

        // Calculate category totals
        const latestPoint = trendData[trendData.length - 1] || {};
        const categoryStats = [
          { name: 'Recyclable', value: latestPoint.recyclable || 0, color: '#14b8a6' },
          { name: 'Wet', value: latestPoint.wet || 0, color: '#2dd4bf' },
          { name: 'Hazardous', value: latestPoint.hazardous || 0, color: '#f43f5e' },
          { name: 'Dry', value: latestPoint.dry || 0, color: '#64748b' },
        ];

        return (
          <div className="space-y-4">
            {/* Controls Bar */}
            <div className="flex items-center justify-between flex-wrap gap-3 p-3 rounded-xl bg-white/5 border border-white/10">
              {/* Time Range Selector */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-slate-400 font-medium">Range:</span>
                <div className="flex gap-1">
                  {['5m', '1h', 'today', 'week', 'all'].map(r => (
                    <button
                      key={r}
                      onClick={() => setChartTimeRange(r)}
                      className={`px-3 py-1.5 text-xs font-semibold rounded-lg capitalize transition-all ${chartTimeRange === r
                        ? 'bg-gradient-to-r from-cyan-500 to-teal-500 text-white shadow-lg'
                        : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'
                        }`}
                    >
                      {r}
                    </button>
                  ))}
                </div>
              </div>

              {/* Trend Delta Badge */}
              <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg ${trendDelta >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-rose-500/20 text-rose-400'
                }`}>
                <span className="text-lg font-bold">{trendDelta >= 0 ? '+' : ''}{trendDelta}%</span>
                <span className="text-xs opacity-80">vs start</span>
              </div>
            </div>

            {/* Main Chart */}
            <EnhancedAreaChart data={trendData} height={300} timeRange={chartTimeRange} />

            {/* Category Stats Grid */}
            <div className="grid grid-cols-4 gap-3">
              {categoryStats.map(stat => (
                <div key={stat.name} className="p-3 rounded-xl bg-white/5 border border-white/10 text-center">
                  <div className="w-3 h-3 rounded-full mx-auto mb-2" style={{ backgroundColor: stat.color }} />
                  <div className="text-xl font-bold text-white">{stat.value}</div>
                  <div className="text-xs text-slate-400">{stat.name}</div>
                </div>
              ))}
            </div>

            {/* Info Footer */}
            <div className="text-center text-xs text-slate-500">
              Data updates every 10 seconds ΓÇó Showing {trendData.length} data points
            </div>
          </div>
        );
      case 'session':
        // Mock history for session comparison
        const histFactor = 1 + (historyValue * 0.1);
        return (
          <ResponsiveContainer width="100%" height={400} minWidth={0} minHeight={0}>
            <BarChart data={[
              { name: 'Total', current: processingCounts.total * histFactor, average: processingCounts.total * 0.8 },
              { name: 'Rec', current: processingCounts.recyclable * histFactor, average: processingCounts.recyclable * 0.9 },
              { name: 'Wet', current: processingCounts.wet * histFactor, average: processingCounts.wet * 0.7 },
              { name: 'Haz', current: processingCounts.hazardous * histFactor, average: processingCounts.hazardous * 1.1 },
              { name: 'Dry', current: processingCounts.dry * histFactor, average: processingCounts.dry * 0.5 }
            ]} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
              <XAxis dataKey="name" stroke="#64748b" />
              <YAxis stroke="#64748b" />
              <Tooltip content={<GlassTooltip />} />
              <Legend wrapperStyle={{ paddingTop: '20px' }} />
              <Bar dataKey="current" name={historyValue === 0 ? "Current Session" : "Past Session"} fill="#2dd4bf" radius={[4, 4, 0, 0]} />
              <Bar dataKey="average" name="Historical Avg" fill="#94a3b8" radius={[4, 4, 0, 0]} fillOpacity={0.3} />
            </BarChart>
          </ResponsiveContainer>
        );
      case 'hourly':
        return <HourlyStackedBarChart data={hourlyData} height={400} />;
      case 'confidence':
        // Shift confidence distribution for history or use mock distribution
        const confData = [
          { range: '0-20%', count: 2 + Math.abs(historyValue) },
          { range: '20-40%', count: 5 + Math.abs(historyValue) },
          { range: '40-60%', count: 8 + Math.abs(historyValue) },
          { range: '60-80%', count: 12 + Math.abs(historyValue) },
          { range: '80-100%', count: 25 - Math.abs(historyValue) }
        ];
        return <ConfidenceHistogram data={confData} height={400} />;
      case 'predictive':
        // Shift prediction curve
        const offset = Math.abs(historyValue) * 5;
        const predictiveData = [
          { time: '10:00', actual: 45 - offset, predicted: 45 - offset, threshold: 80 },
          { time: '11:00', actual: 52 - offset, predicted: 50 - offset, threshold: 80 },
          { time: '12:00', actual: 68 - offset, predicted: 65 - offset, threshold: 80 },
          { time: '13:00', actual: 75 - offset, predicted: 78 - offset, threshold: 80 },
