      // --- Eco Metrics Calculation ---
      // Formulas based on average recycling data
      const totalWeight = data.bins?.reduce((acc, b) => acc + (b.weight || 0), 0) || 0;
      setEcoMetrics({
        co2Offset: (totalWeight * 1.51).toFixed(2),      // 1.51kg CO2 saved per kg recycled
