      const newPredictions = { ...predictedFillTimes };

      data.bins?.forEach(bin => {
        const prevVol = prevBinVolumes.current[bin.id] || 0;
        const volDelta = bin.volume - prevVol;

        // Update sliding window (keep last 10 samples approx 100s)
