            );
        } else if (expandedGraph.graphId === 'area') {
            historyChart = (
                <ResponsiveContainer width="100%" height={400}>
                    <AreaChart data={tsd}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="time" />
                        <YAxis />
                        <Tooltip />
                        <Area type="monotone" dataKey="bio" stackId="1" fill="url(#gradientBio)" stroke="#10b981" />
