// ===== GRADIENT AREA CHART (Enhanced) =====
export const EnhancedAreaChart = ({
    data = [],
    categories = ['recyclable', 'hazardous', 'wet', 'dry'],
    height = 200,
    timeRange = 'all',
    showLegend = true
}) => {
    // Filter data based on time range
    const filteredData = useMemo(() => {
        if (timeRange === 'all' || !data.length) return data;
        // Map time ranges to number of data points to show
        const sliceMap = {
            '5m': 5,      // ~50 seconds at 10s intervals
            '15m': 15,    // ~2.5 minutes
            '1h': 30,     // ~5 minutes
            'today': 100, // Last 100 points (~16 minutes)
            'week': data.length // Show all available (max 500)
        };
        return data.slice(-(sliceMap[timeRange] || data.length));
    }, [data, timeRange]);

    return (
        <div className="w-full chart-animate">
            <ResponsiveContainer width="100%" height={height} minWidth={0} minHeight={0}>
                <AreaChart data={filteredData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    {/* Gradient Definitions */}
                    <defs>
                        <linearGradient id="gradientRecyclable" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#14b8a6" stopOpacity={0.5} />
                            <stop offset="100%" stopColor="#14b8a6" stopOpacity={0.02} />
                        </linearGradient>
                        <linearGradient id="gradientHazardous" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#64748b" stopOpacity={0.5} />
                            <stop offset="100%" stopColor="#64748b" stopOpacity={0.02} />
                        </linearGradient>
                        <linearGradient id="gradientWet" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#2dd4bf" stopOpacity={0.5} />
                            <stop offset="100%" stopColor="#2dd4bf" stopOpacity={0.02} />
                        </linearGradient>
                        <linearGradient id="gradientDry" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#94a3b8" stopOpacity={0.5} />
                            <stop offset="100%" stopColor="#94a3b8" stopOpacity={0.02} />
                        </linearGradient>
                        {/* Glow filter */}
                        <filter id="glow">
                            <feGaussianBlur stdDeviation="2" result="coloredBlur" />
                            <feMerge>
                                <feMergeNode in="coloredBlur" />
                                <feMergeNode in="SourceGraphic" />
                            </feMerge>
                        </filter>
                    </defs>

                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.03)" />
                    <XAxis
                        dataKey="time"
                        tick={{ fill: '#64748b', fontSize: 10 }}
                        axisLine={{ stroke: 'rgba(255,255,255,0.05)' }}
                        tickLine={false}
                    />
                    <YAxis
                        tick={{ fill: '#64748b', fontSize: 10 }}
                        axisLine={{ stroke: 'rgba(255,255,255,0.05)' }}
                        tickLine={false}
                    />
                    <Tooltip content={<GlassTooltip />} />
                    {showLegend && (
                        <Legend
                            wrapperStyle={{ paddingTop: '10px' }}
                            iconType="circle"
                            iconSize={8}
                        />
                    )}

                    {categories.map(cat => (
                        <Area
                            key={cat}
                            type="monotone"
                            dataKey={cat}
                            name={cat.charAt(0).toUpperCase() + cat.slice(1)}
                            stroke={CATEGORY_COLORS[cat].main}
                            strokeWidth={2}
                            fill={CATEGORY_COLORS[cat].gradient}
