                    <Pie
                        activeIndex={activeIndex}
                        activeShape={renderActiveShape}
                        data={chartData}
                        cx="50%"
                        cy="50%"
                        innerRadius={height * 0.25}
                        outerRadius={height * 0.38}
                        paddingAngle={3}
                        dataKey="value"
                        onMouseEnter={onPieEnter}
